def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if grid[h - 1][c] != 5:
            continue
        next_value = None
        for r in range(h - 1, -1, -1):
            if grid[r][c] != 0:
                next_value = grid[r][c]
            out[r][c] = next_value
    return out
